&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;
&lt;/div&gt;
Ces objets sont des capes, des houppelandes, des p&#232;lerines, des manteaux, des spalli&#232;res, des ch&#226;les, des &#233;toles, des ailes et tous les objets pouvant &#234;tre port&#233;s sur les &#233;paules.&lt;br /&gt;&lt;br /&gt;Tout le monde peut utiliser un objet merveilleux port&#233; sur les &#233;paules &#224; moins que le contraire ne soit indiqu&#233; dans sa description. Ces objets sont habituellement activ&#233;s par usage ou par un mot de commande mais il y a parfois des diff&#233;rences en fonction des objets. &lt;br /&gt;&lt;br /&gt;Tous les objets merveilleux d&#233;crits ci-dessous p&#232;sent entre 0,125 g et 2 kg sauf les &lt;i&gt;Spalli&#232;res &#192; Pointes D&#233;moniaques&lt;/i&gt; qui p&#232;sent 4 kg.&lt;br /&gt;&lt;br /&gt;&lt;script type=&quot;text/javascript&quot;&gt;
$(filtrable_init);

function filtrable_init() {
    // Find all tables with class filtrable and make them filtrable
    $(&quot;table.filtrable&quot;).each(makeFiltrable);
}

function makeFiltrable() {
    var table = $(this);
    var rows = table.find(&quot;tr&quot;);
    if (rows.length &lt; 2) {
        return;
    }
    var firstRow = rows.first();
    var cells = firstRow.children(&quot;td,th&quot;);
    table.get()[0].filters = [];
    cells.each(function (idx) {
        var contents = $(this).html;
        var filterLogo = $(&quot;&lt;img height=&#39;12px&#39; /&gt;&quot;);
        filterLogo.attr(&#39;src&#39;, &#39;/wiki/public/Upload/Battlemaps/Boutons/filter.png&#39;);
        filterLogo.attr(&#39;title&#39;, &#39;Cliquez ici pour filtrer les donn&#233;es&#39;);
        filterLogo.css(&#39;padding&#39;, &#39;0&#39;);
        filterLogo.click(doFilter(idx,filterLogo,table));
        $(this).prepend(filterLogo);
        table.get()[0].filters.push(null);
    });
}
function doFilter(nCol, logo, table) {
    return function () {
        var filter = prompt(&quot;Entrez le filtre &#224; appliquer.\nLaisser le cadre vide pour tout afficher; utilisez &#39;mot1|mot2&#39; pour un choix multiple.&quot;, &quot;&quot;).trim();
        if (filter == &quot;&quot;) {
            table.get()[0].filters[nCol] = null;
            logo.css(&quot;background-color&quot;, &quot;&quot;);
            logo.attr(&quot;title&quot;,&quot;Filtre actuel : aucun - cliquez pour changer le filtre&quot;);
        } else {
            table.get()[0].filters[nCol] = new RegExp(filter.trim(),&quot;i&quot;);
            logo.css(&quot;background-color&quot;, &quot;yellow&quot;);
            logo.attr(&quot;title&quot;,&quot;Filtre actuel : &quot; + (filter == &quot;&quot; ? &quot;aucun&quot; : filter)
                + &quot; - cliquez pour changer le filtre&quot;);
        }
        applyFilter(table);
    };
}
function applyFilter(table) {
    var rows = table.find(&quot;tr&quot;).filter(function (idx) {
        return idx &gt; 0 &amp;&amp; $(this).children(&quot;th&quot;).length == 0;
    });
    rows.each(function () {
        var keep = mustKeep(this,table.get()[0].filters);
        $(this).css(&quot;display&quot;, keep ? &quot;table-row&quot; : &quot;none&quot;);
    });
}
function mustKeep(row,filters) {
    var cells = $(row).children(&quot;td&quot;);
    var nCols = filters.length;
    var keep = true;
    var iCol = 0;
    while (keep &amp;&amp; iCol &lt; nCols) {
        keep = filters[iCol] === null ||
            cells.eq(iCol).html().match(filters[iCol]) != null;
        iCol++;
    }
    return keep;
}
&lt;/script&gt;
&lt;table CLASS=&quot;tablo centre autoalt toutgauche filtrable&quot;&gt;&lt;caption&gt;Objets merveilleux port&#233;s sur les &#233;paules&lt;/caption&gt;&lt;tr CLASS=&quot;titre&quot;&gt;&lt;td WIDTH=&quot;22%&quot;&gt;Objet&lt;/td&gt;&lt;td WIDTH= &quot;3%&quot;&gt;Source&lt;/td&gt;&lt;td WIDTH=&quot;65%&quot;&gt;Capacit&#233;s&lt;/td&gt;&lt;td WIDTH=&quot;10%&quot;&gt;Prix de vente&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Cape-Enveloppante.html&quot; title=&quot;Cape enveloppante&quot;&gt;Cape enveloppante&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MJRA, A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Peut conf&#233;rer un &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat.html#CAMOUFLAGE&quot; title=&quot;Valeurs de combat&quot;&gt;camouflage&lt;/a&gt; de 20&#160;% pendant 1 minute ou jusqu’&#224; ce que ce dernier &#233;vite le porteur de se faire toucher. Usage unique.&lt;/td&gt;&lt;td&gt;200 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Cape-De-D&#233;guisement-Humain.html&quot; title=&quot;Cape de d&#233;guisement humain&quot;&gt;Cape de d&#233;guisement humain&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E, MR&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Efface les traits particuliers d’un personnage de race demi-humaine tant qu’il la porte.&lt;/td&gt;&lt;td&gt;900 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Cape-De-R&#233;sistance.html&quot; title=&quot;Cape de r&#233;sistance&quot;&gt;Cape de r&#233;sistance&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MJ, A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;re un bonus de r&#233;sistance aux &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat.html#JETDESAUVEGARDE&quot; title=&quot;Valeurs de combat&quot;&gt;jets de sauvegarde&lt;/a&gt;.&lt;/td&gt;&lt;td&gt;—&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&amp;emsp; +1&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MJ, A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Le bonus s’&#233;l&#232;ve &#224; +1.&lt;/td&gt;&lt;td&gt;1 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&amp;emsp; +2&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MJ, A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Le bonus s’&#233;l&#232;ve &#224; +2.&lt;/td&gt;&lt;td&gt;| 4 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&amp;emsp; +3&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MJ, A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Le bonus s’&#233;l&#232;ve &#224; +3.&lt;/td&gt;&lt;td&gt;| 9 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&amp;emsp; +4&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MJ, A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Le bonus s’&#233;l&#232;ve &#224; +4.&lt;/td&gt;&lt;td&gt;| 16 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&amp;emsp; +5&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MJ, A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Le bonus s’&#233;l&#232;ve &#224; +5.&lt;/td&gt;&lt;td&gt;| 25 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Cape-D&#233;fensive.html&quot; title=&quot;Cape d&#233;fensive&quot;&gt;Cape d&#233;fensive&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Peut se transformer en rondache de ma&#238;tre en bois &#224; volont&#233;, elle peut &#234;tre enchant&#233;e.&lt;/td&gt;&lt;td&gt;1 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Ch&#226;le-De-Transfert-Vital.html&quot; title=&quot;Ch&#226;le de transfert vital&quot;&gt;Ch&#226;le de transfert vital&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E, MR&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Une fois par jour, peut stocker jusqu’&#224; 10 points de vie du porteur et les lui rendre s’il tombe &#224; -1 points de vie ou moins. Ne peut pas emp&#234;cher de mourir. Affaiblie la cr&#233;ature dont les points de vie sont stock&#233;s si elle ne la porte pas.&lt;/td&gt;&lt;td&gt;1 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Cordes-De-Mulet.html&quot; title=&quot;Cordes de mulet&quot;&gt;Cordes de mulet&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Le porteur ajoute 8 &#224; sa valeur de &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Force.html&quot; title=&quot;La Force&quot;&gt;Force&lt;/a&gt; pour calculer sa charge transportable.&lt;/td&gt;&lt;td&gt;1 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Cape-De-Libre-Arbitre.html&quot; title=&quot;Cape de libre arbitre&quot;&gt;Cape de libre arbitre&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;CMy&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;re un bonus de r&#233;sistance aux &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;JDS&quot;&gt;jets de sauvegarde&lt;/a&gt; d&#233;pendant du mod&#232;le, qui est sup&#233;rieur de 1 pour la &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;Volont&#233;&quot;&gt;Volont&#233;&lt;/a&gt;. S&#39;il rate un jet de Volont&#233;, le porteur peut d&#233;penser une utilisation de &lt;a class=&quot;pagelink&quot; href=&quot;Glossaire-Mythique#Pouvoirmythique.html&quot; title=&quot;pouvoir mythique&quot;&gt;pouvoir mythique&lt;/a&gt; pour relancer le jet (si le second jet est rat&#233;, ce pouvoir est d&#233;sactiv&#233; pendant 24 heures).&lt;/td&gt;&lt;td&gt;—&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&amp;emsp; +1/+2&lt;/td&gt;&lt;td&gt;&lt;sup&gt;CMy&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Le bonus s’&#233;l&#232;ve &#224; +1 et &#224; +2 pour la Volont&#233;.&lt;/td&gt;&lt;td&gt;1 500 po&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&amp;emsp; +2/+3&lt;/td&gt;&lt;td&gt;&lt;sup&gt;CMy&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Le bonus s’&#233;l&#232;ve &#224; +2 et &#224; +3 pour la Volont&#233;.&lt;/td&gt;&lt;td&gt;6 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&amp;emsp; +3/+4&lt;/td&gt;&lt;td&gt;&lt;sup&gt;CMy&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Le bonus s’&#233;l&#232;ve &#224; +3 et &#224; +4 pour la Volont&#233;.&lt;/td&gt;&lt;td&gt;13 500 po&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&amp;emsp; +4/+5&lt;/td&gt;&lt;td&gt;&lt;sup&gt;CMy&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Le bonus s’&#233;l&#232;ve &#224; +4 et &#224; +5 pour la Volont&#233;.&lt;/td&gt;&lt;td&gt;24 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&amp;emsp; +5/+6&lt;/td&gt;&lt;td&gt;&lt;sup&gt;CMy&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Le bonus s’&#233;l&#232;ve &#224; +5 et &#224; +6 pour la Volont&#233;.&lt;/td&gt;&lt;td&gt;37 500 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Cape-De-R&#233;flexes-Rapides.html&quot; title=&quot;Cape de r&#233;flexes rapides&quot;&gt;Cape de r&#233;flexes rapides&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;CMy&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;re un bonus de r&#233;sistance aux &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;JDS&quot;&gt;jets de sauvegarde&lt;/a&gt; d&#233;pendant du mod&#232;le, qui est sup&#233;rieur de 1 pour les &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;R&#233;flexes&quot;&gt;R&#233;flexes&lt;/a&gt;. S&#39;il rate un jet de R&#233;flexes, le porteur peut d&#233;penser une utilisation de &lt;a class=&quot;pagelink&quot; href=&quot;Glossaire-Mythique#Pouvoirmythique.html&quot; title=&quot;pouvoir mythique&quot;&gt;pouvoir mythique&lt;/a&gt; pour relancer le jet (si le second jet est rat&#233;, ce pouvoir est d&#233;sactiv&#233; pendant 24 heures).&lt;/td&gt;&lt;td&gt;—&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&amp;emsp; +1/+2&lt;/td&gt;&lt;td&gt;&lt;sup&gt;CMy&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Le bonus s’&#233;l&#232;ve &#224; +1 et &#224; +2 pour les R&#233;flexes.&lt;/td&gt;&lt;td&gt;1 500 po&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&amp;emsp; +2/+3&lt;/td&gt;&lt;td&gt;&lt;sup&gt;CMy&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Le bonus s’&#233;l&#232;ve &#224; +2 et &#224; +3 pour les R&#233;flexes.&lt;/td&gt;&lt;td&gt;6 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&amp;emsp; +3/+4&lt;/td&gt;&lt;td&gt;&lt;sup&gt;CMy&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Le bonus s’&#233;l&#232;ve &#224; +3 et &#224; +4 pour les R&#233;flexes.&lt;/td&gt;&lt;td&gt;13 500 po&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&amp;emsp; +4/+5&lt;/td&gt;&lt;td&gt;&lt;sup&gt;CMy&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Le bonus s’&#233;l&#232;ve &#224; +4 et &#224; +5 pour les R&#233;flexes.&lt;/td&gt;&lt;td&gt;24 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&amp;emsp; +5/+6&lt;/td&gt;&lt;td&gt;&lt;sup&gt;CMy&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Le bonus s’&#233;l&#232;ve &#224; +5 et &#224; +6 pour les R&#233;flexes.&lt;/td&gt;&lt;td&gt;37 500 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Cape-De-Transformiste.html&quot; title=&quot;Cape de transformiste&quot;&gt;Cape de transformiste&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Peut stocker jusqu’&#224; 3 d&#233;guisements (r&#233;alis&#233;s avec la comp&#233;tence &lt;a class=&quot;pagelink&quot; href=&quot;D&#233;guisement.html&quot; title=&quot;D&#233;guisement&quot;&gt;D&#233;guisement&lt;/a&gt;) que le porteur peut rev&#234;tir librement.&lt;/td&gt;&lt;td&gt;1 500 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;&#201;pauli&#232;res-De-Vigueur-In&#233;branlable.html&quot; title=&quot;&#201;pauli&#232;res de vigueur in&#233;branlable&quot;&gt;&#233;pauli&#232;res de vigueur in&#233;branlable&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;CMy&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;re un bonus de r&#233;sistance aux &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;JDS&quot;&gt;jets de sauvegarde&lt;/a&gt; d&#233;pendant du mod&#232;le, qui est sup&#233;rieur de 1 pour les &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;Vigueur&quot;&gt;Vigueur&lt;/a&gt;. S&#39;il rate un jet de Vigueur, le porteur peut d&#233;penser une utilisation de &lt;a class=&quot;pagelink&quot; href=&quot;Glossaire-Mythique#Pouvoirmythique.html&quot; title=&quot;pouvoir mythique&quot;&gt;pouvoir mythique&lt;/a&gt; pour relancer le jet (si le second jet est rat&#233;, ce pouvoir est d&#233;sactiv&#233; pendant 24 heures).&lt;/td&gt;&lt;td&gt;—&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&amp;emsp; +1/+2&lt;/td&gt;&lt;td&gt;&lt;sup&gt;CMy&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Le bonus s’&#233;l&#232;ve &#224; +1 et &#224; +2 pour la Vigueur.&lt;/td&gt;&lt;td&gt;1 500 po&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&amp;emsp; +2/+3&lt;/td&gt;&lt;td&gt;&lt;sup&gt;CMy&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Le bonus s’&#233;l&#232;ve &#224; +2 et &#224; +3 pour la Vigueur.&lt;/td&gt;&lt;td&gt;6 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&amp;emsp; +3/+4&lt;/td&gt;&lt;td&gt;&lt;sup&gt;CMy&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Le bonus s’&#233;l&#232;ve &#224; +3 et &#224; +4 pour la Vigueur.&lt;/td&gt;&lt;td&gt;13 500 po&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&amp;emsp; +4/+5&lt;/td&gt;&lt;td&gt;&lt;sup&gt;CMy&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Le bonus s’&#233;l&#232;ve &#224; +4 et &#224; +5 pour la Vigueur.&lt;/td&gt;&lt;td&gt;24 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&amp;emsp; +5/+6&lt;/td&gt;&lt;td&gt;&lt;sup&gt;CMy&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Le bonus s’&#233;l&#232;ve &#224; +5 et &#224; +6 pour la Vigueur.&lt;/td&gt;&lt;td&gt;37 500 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Cape-Du-L&#226;che-Accroupi.html&quot; title=&quot;Cape du l&#226;che accroupi&quot;&gt;Cape du l&#226;che accroupi&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MJRA, A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Peut forcer les assaillants &#224; r&#233;ussir un jet de &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;Volont&#233;&quot;&gt;Volont&#233;&lt;/a&gt; pour porter leurs attaques (comme avec &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Sanctuaire.html&quot; title=&quot;Sanctuaire&quot;&gt;sanctuaire&lt;/a&gt;&lt;/i&gt;). Ce pouvoir occulte la vision du porteur et l’emp&#234;che d’agir.&lt;/td&gt;&lt;td&gt;1 800 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Cape-Du-Ciel-Nocturne.html&quot; title=&quot;Cape du ciel nocturne&quot;&gt;Cape du ciel nocturne&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;D&amp;M, &lt;i&gt;ISG&lt;/i&gt;&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Prot&#232;ge de la chaleur et du froid (comme avec &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Endurance-Aux-&#201;nergies-Destructives.html&quot; title=&quot;Endurance aux &#233;nergies destructives&quot;&gt;endurance aux &#233;nergies destructives&lt;/a&gt;&lt;/i&gt; quand le porteur dort. Permet de dormir en armure interm&#233;diaire sans cons&#233;quence. Une fois par jour, permet de lancer &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Rep&#233;rage.html&quot; title=&quot;Rep&#233;rage&quot;&gt;rep&#233;rage&lt;/a&gt;&lt;/i&gt;. Un suivant de &lt;a class=&quot;pagelink&quot; href=&quot;Desna-(Technique).html&quot; title=&quot;Desna&quot;&gt;Desna&lt;/a&gt; peut faire appara&#238;tre la configuration c&#233;leste actuelle sur l&#39;objet, et lancer &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Grand-Pas.html&quot; title=&quot;Grand pas&quot;&gt;grand pas&lt;/a&gt;&lt;/i&gt; et &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Illumination.html&quot; title=&quot;Illumination&quot;&gt;illumination&lt;/a&gt;&lt;/i&gt; une fois par jour.&lt;/td&gt;&lt;td&gt;2 500 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Cape-Du-Magicien-Solitaire.html&quot; title=&quot;Cape du magicien solitaire&quot;&gt;Cape du magicien solitaire&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Permet de lancer &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Prestidigitation.html&quot; title=&quot;Prestidigitation&quot;&gt;prestidigitation&lt;/a&gt;&lt;/i&gt; &#224; volont&#233;. Permet de lancer plusieurs sorts selon l’&#233;cole de magie choisie &#224; la fabrication.&lt;/td&gt;&lt;td&gt;2 500 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Cape-Elfique.html&quot; title=&quot;Cape elfique&quot;&gt;Cape elfique&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MJ, A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;re un bonus de comp&#233;tence de +5 aux tests de &lt;a class=&quot;pagelink&quot; href=&quot;Discr&#233;tion.html&quot; title=&quot;Discr&#233;tion&quot;&gt;Discr&#233;tion&lt;/a&gt;.&lt;/td&gt;&lt;td&gt;2 500 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Cape-De-Disparition-Enflamm&#233;e.html&quot; title=&quot;Cape de disparition enflamm&#233;e&quot;&gt;Cape de disparition enflamm&#233;e&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E, MR&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Lorsque le porteur subit un effet infligeant des d&#233;g&#226;ts de feu, laisse une illusion de son corps en cendres et conf&#232;re les effets du sort &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Invisibilit&#233;.html&quot; title=&quot;Invisibilit&#233;&quot;&gt;invisibilit&#233;&lt;/a&gt;&lt;/i&gt; pendant 5 &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Round.html&quot; title=&quot;round&quot;&gt;rounds&lt;/a&gt; maximum.&lt;/td&gt;&lt;td&gt;2 600 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Cape-De-La-Crois&#233;e.html&quot; title=&quot;Cape de la crois&#233;e&quot;&gt;Cape de la crois&#233;e&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;D&amp;M, &lt;i&gt;ISG&lt;/i&gt;&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Une fois par jour, permet de lancer &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;B&#233;n&#233;diction.html&quot; title=&quot;B&#233;n&#233;diction&quot;&gt;b&#233;n&#233;diction&lt;/a&gt;&lt;/i&gt;. Un suivant d&#39;&lt;a class=&quot;pagelink&quot; href=&quot;Iom&#233;dae-(Technique).html&quot; title=&quot;Iom&#233;dae&quot;&gt;Iom&#233;dae&lt;/a&gt; b&#233;n&#233;ficie d&#39;un bonus d&#39;alt&#233;ration de +1 &#224; l&#39;armure naturelle, et peut manifester une banni&#232;re sainte au dessus de sa t&#234;te &#224; volont&#233;.&lt;/td&gt;&lt;td&gt;2 700 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Cape-Du-Traqueur-De-Mort.html&quot; title=&quot;Cape du traqueur de mort&quot;&gt;Cape du traqueur de mort&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;D&amp;M, &lt;i&gt;ISG&lt;/i&gt;&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Une fois par jour, permet de lancer &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Anath&#232;me.html&quot; title=&quot;Anath&#232;me&quot;&gt;anath&#232;me&lt;/a&gt;&lt;/i&gt;. Un suivant de &lt;a class=&quot;pagelink&quot; href=&quot;Gro&#233;tus-(Technique).html&quot; title=&quot;Gro&#233;tus&quot;&gt;Gro&#233;tus&lt;/a&gt; peut lancer &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Simulacre-De-Vie.html&quot; title=&quot;Simulacre de vie&quot;&gt;simulacre de vie&lt;/a&gt;&lt;/i&gt; (renforc&#233; &#224; chaque ennemi tu&#233;) une fois par jour.&lt;/td&gt;&lt;td&gt;2 700 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Cape-De-Crocs.html&quot; title=&quot;Cape de crocs&quot;&gt;Cape de crocs&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E, MR&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;re un bonus de r&#233;sistance de +1 aux &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat.html#JETDESAUVEGARDE&quot; title=&quot;Valeurs de combat&quot;&gt;jets de sauvegarde&lt;/a&gt;. Cinq fois par jour, peut conf&#233;rer une attaque de morsure infligeant 1d6 points de d&#233;g&#226;ts pendant 1 &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Round.html&quot; title=&quot;round&quot;&gt;round&lt;/a&gt; (si le porteur en poss&#232;de d&#233;j&#224; une, sa taille augmente d’une cat&#233;gorie pour en d&#233;terminer les d&#233;g&#226;ts).&lt;/td&gt;&lt;td&gt;2 800 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Cape-Du-Grand-H&#233;ros-Barghest.html&quot; title=&quot;Cape du grand h&#233;ros barghest&quot;&gt;Cape du grand h&#233;ros barghest&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;D&amp;M, &lt;i&gt;ISG&lt;/i&gt;&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;re un bonus de comp&#233;tence de +2 aux tests d&#39;&lt;a class=&quot;pagelink&quot; href=&quot;Intimidation.html&quot; title=&quot;Intimidation&quot;&gt;Intimidation&lt;/a&gt;. Un suivant d&#39;un des h&#233;ros barghests gobelins peut lancer &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;M&#233;tamorphose.html&quot; title=&quot;M&#233;tamorphose&quot;&gt;m&#233;tamorphose&lt;/a&gt;&lt;/i&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Chien-Gobelin.html&quot; title=&quot;Chien gobelin&quot;&gt;chien gobelin&lt;/a&gt; uniquement) une fois par jour.&lt;/td&gt;&lt;td&gt;2 800 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;&#201;paulettes-Dor&#233;es-De-Laigle.html&quot; title=&quot;&#201;paulettes dor&#233;es de l&amp;#39;aigle&quot;&gt;&#233;paulettes dor&#233;es de l&#39;aigle&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;RSE&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;re un bonus de comp&#233;tence de +2 aux tests de &lt;a class=&quot;pagelink&quot; href=&quot;Diplomatie.html&quot; title=&quot;Diplomatie&quot;&gt;Diplomatie&lt;/a&gt; et &#224; une autre comp&#233;tence choisie &#224; la fabrication. Une fois par jour, permet de lancer &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;B&#233;n&#233;diction.html&quot; title=&quot;B&#233;n&#233;diction&quot;&gt;b&#233;n&#233;diction&lt;/a&gt;&lt;/i&gt;. Quand le porteur tombe &#224; 0 &lt;a class=&quot;pagelink&quot; href=&quot;Point-De-Vie.html&quot; title=&quot;pv&quot;&gt;pv&lt;/a&gt;, conf&#232;re les effets de &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Sanctuaire.html&quot; title=&quot;Sanctuaire&quot;&gt;sanctuaire&lt;/a&gt;&lt;/i&gt;.&lt;/td&gt;&lt;td&gt;3 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Spalli&#232;res-Du-Serpent.html&quot; title=&quot;Spalli&#232;res du serpent&quot;&gt;Spalli&#232;res du serpent&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;re un bonus d’esquive de +2 &#224; la &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Ca.html&quot; title=&quot;CA&quot;&gt;CA&lt;/a&gt; contre les &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat.html#ATTAQUEDOPPORTUNITE&quot; title=&quot;Valeurs de combat&quot;&gt;attaques d’opportunit&#233;&lt;/a&gt; et un bonus de +1 au &lt;a class=&quot;pagelink&quot; href=&quot;Manœuvres-Offensives#Dmd.html&quot; title=&quot;DMD&quot;&gt;DMD&lt;/a&gt; contre les manœuvres de &lt;a class=&quot;pagelink&quot; href=&quot;Manœuvres-Offensives.html#BOUSCULADE&quot; title=&quot;Les manœuvres offensives&quot;&gt;bousculade&lt;/a&gt;, de &lt;a class=&quot;pagelink&quot; href=&quot;Manœuvres-Offensives.html#LUTTE&quot; title=&quot;Les manœuvres offensives&quot;&gt;lutte&lt;/a&gt;, de &lt;a class=&quot;pagelink&quot; href=&quot;Manœuvres-Offensives.html#REPOSITIONNEMENT&quot; title=&quot;Les manœuvres offensives&quot;&gt;repositionnement&lt;/a&gt; et de &lt;a class=&quot;pagelink&quot; href=&quot;Manœuvres-Offensives.html#CROCENJAMBE&quot; title=&quot;Les manœuvres offensives&quot;&gt;croc-en-jambe&lt;/a&gt;.&lt;/td&gt;&lt;td&gt;3 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Cape-Dalarme-Sanglante.html&quot; title=&quot;Cape d&amp;#39;alarme sanglante&quot;&gt;Cape d&#39;alarme sanglante&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;&lt;i&gt;ISR&lt;/i&gt;&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Une fois par jour, les blessures d&#39;un porteur &lt;a class=&quot;pagelink&quot; href=&quot;Homme-Rat-(Race).html&quot; title=&quot;Les hommes-rats&quot;&gt;homme-rat&lt;/a&gt; alertent automatiquement l&#39;alli&#233; homme-rat le plus proche dans un rayon de 1,5 km.&lt;/td&gt;&lt;td&gt;3 200 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Peau-Dours-Du-Briseur-Dos.html&quot; title=&quot;Peau d&amp;#39;ours du briseur d&amp;#39;os&quot;&gt;Peau d&#39;ours du briseur d&#39;os&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;D&amp;M, &lt;i&gt;ISG&lt;/i&gt;&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;re un bonus de comp&#233;tence de +2 aux tests d&#39;&lt;a class=&quot;pagelink&quot; href=&quot;Intimidation.html&quot; title=&quot;Intimidation&quot;&gt;Intimidation&lt;/a&gt;. Une fois par jour, permet de lancer &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;B&#233;n&#233;diction.html&quot; title=&quot;B&#233;n&#233;diction&quot;&gt;b&#233;n&#233;diction&lt;/a&gt;&lt;/i&gt;. Un suivant d&#39;Urazra peut lancer &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Forme-Bestiale-Ii.html&quot; title=&quot;Forme bestiale II&quot;&gt;forme bestiale II&lt;/a&gt;&lt;/i&gt; (ours noir ou brun) une fois par jour.&lt;/td&gt;&lt;td&gt;3 300 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Cape-Des-Brumes-Montagneuses.html&quot; title=&quot;Cape des brumes montagneuses&quot;&gt;Cape des brumes montagneuses&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E, MR&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;re un bonus de comp&#233;tence de +5 aux tests de &lt;a class=&quot;pagelink&quot; href=&quot;Discr&#233;tion.html&quot; title=&quot;Discr&#233;tion&quot;&gt;Discr&#233;tion&lt;/a&gt;. Une fois par jour, permet de lancer &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Brume-De-Dissimulation.html&quot; title=&quot;Brume de dissimulation&quot;&gt;brume de dissimulation&lt;/a&gt;&lt;/i&gt;.&lt;/td&gt;&lt;td&gt;3 500 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Cape-De-Plum&#233;cailles.html&quot; title=&quot;Cape de plum&#233;cailles&quot;&gt;Cape de plum&#233;cailles&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;&lt;i&gt;ISG&lt;/i&gt;&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;re un bonus de comp&#233;tence de +5 aux tests de &lt;a class=&quot;pagelink&quot; href=&quot;Natation.html&quot; title=&quot;Natation&quot;&gt;Natation&lt;/a&gt;. Une fois par jour, permet de lancer &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Feuille-Morte.html&quot; title=&quot;Feuille morte&quot;&gt;feuille morte&lt;/a&gt;&lt;/i&gt;, &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Forme-Bestiale-I.html&quot; title=&quot;Forme bestiale I&quot;&gt;forme bestiale I&lt;/a&gt;&lt;/i&gt; (oiseau ou en poisson uniquement) et &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Invisibilit&#233;-Pour-Les-Animaux.html&quot; title=&quot;Invisibilit&#233; pour les animaux&quot;&gt;invisibilit&#233; pour les animaux&lt;/a&gt;&lt;/i&gt; (soi-m&#234;me uniquement).&lt;/td&gt;&lt;td&gt;4 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Cape-Du-Grand-Ch&#234;ne.html&quot; title=&quot;Cape du grand ch&#234;ne&quot;&gt;Cape du grand ch&#234;ne&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Une fois par jour, permet de lancer &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Forme-Darbre.html&quot; title=&quot;Forme d&amp;#39;arbre&quot;&gt;forme d’arbre&lt;/a&gt;&lt;/i&gt; (arbre vivant uniquement). Rend 1d6 points de vie par heure pass&#233;e sous cette forme sous la lumi&#232;re du soleil.&lt;/td&gt;&lt;td&gt;6 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Cape-Du-Rat-Sanguinaire.html&quot; title=&quot;Cape du rat sanguinaire&quot;&gt;Cape du rat sanguinaire&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E, MR&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Jusqu’&#224; 5 minutes par jour, permet de se transformer en &lt;a class=&quot;pagelink&quot; href=&quot;Rat-Sanguinaire.html&quot; title=&quot;Rat, Rat sanguinaire&quot;&gt;rat sanguinaire&lt;/a&gt; (comme avec &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Forme-Bestiale-I.html&quot; title=&quot;Forme bestiale I&quot;&gt;forme bestiale I&lt;/a&gt;&lt;/i&gt;).&lt;/td&gt;&lt;td&gt;6 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Ch&#226;le-D&#233;cume-De-Mer.html&quot; title=&quot;Ch&#226;le d’&#233;cume de mer&quot;&gt;Ch&#226;le d’&#233;cume de mer&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E, MR&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Une fois par jour, peut conf&#233;rer les effets du sort &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Petite-Sir&#232;ne.html&quot; title=&quot;Petite sir&#232;ne&quot;&gt;petite sir&#232;ne&lt;/a&gt;&lt;/i&gt; pendant 5 heures maximum.&lt;/td&gt;&lt;td&gt;6 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Suaire-Dun-Mort.html&quot; title=&quot;Suaire d&amp;#39;un mort&quot;&gt;Suaire d&#39;un mort&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;RSE&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;re les effets d&lt;i&gt;&#39;&lt;a class=&quot;pagelink&quot; href=&quot;Invisibilit&#233;-Pour-Les-Morts-Vivants.html&quot; title=&quot;Invisibilit&#233; pour les morts-vivants&quot;&gt;invisibilit&#233; pour les morts-vivants&lt;/a&gt;&lt;/i&gt; en permanence. Une fois par jour, peut rendre le porteur &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables#Invisible.html&quot; title=&quot;Invisible&quot;&gt;invisible&lt;/a&gt; pendant 5 minutes.&lt;/td&gt;&lt;td&gt;6 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Cape-Du-Gredin-Sournois.html&quot; title=&quot;Cape du gredin sournois&quot;&gt;Cape du gredin sournois&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MCA&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;re un bonus de comp&#233;tence de +5 aux tests de &lt;a class=&quot;pagelink&quot; href=&quot;Discr&#233;tion.html&quot; title=&quot;Discr&#233;tion&quot;&gt;Discr&#233;tion&lt;/a&gt;. Peut dissimuler une arme l&#233;g&#232;re qui ne peut &#234;tre rep&#233;r&#233;e qu’avec un test de &lt;a class=&quot;pagelink&quot; href=&quot;Perception.html&quot; title=&quot;Perception&quot;&gt;Perception&lt;/a&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Degrededifficulte.html&quot; title=&quot;DD&quot;&gt;DD&lt;/a&gt; 20 (comme pour un passage secret). Un &lt;a class=&quot;pagelink&quot; href=&quot;Bretteur.html&quot; title=&quot;Le bretteur&quot;&gt;bretteur&lt;/a&gt; peut d&#233;penser 1 point de &lt;a class=&quot;pagelink&quot; href=&quot;Bretteur#Panache.html&quot; title=&quot;panache&quot;&gt;panache&lt;/a&gt; pour b&#233;n&#233;ficier des effets du sort &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Disparition.html&quot; title=&quot;Disparition&quot;&gt;disparition&lt;/a&gt;&lt;/i&gt; pendant 5 &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Round.html&quot; title=&quot;round&quot;&gt;rounds&lt;/a&gt;, &#224; volont&#233;.&lt;/td&gt;&lt;td&gt;6 400 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Cape-De-Laigle.html&quot; title=&quot;Cape de l’aigle&quot;&gt;Cape de l’aigle&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;re les effets du sort &lt;a class=&quot;pagelink&quot; href=&quot;Feuille-Morte.html&quot; title=&quot;Feuille morte&quot;&gt;feuille morte&lt;/a&gt; d&#232;s que son porteur fait une chute d’au moins 1,50 m. Une fois par jour, permet de se transformer en &lt;a class=&quot;pagelink&quot; href=&quot;Aigle.html&quot; title=&quot;Aigle&quot;&gt;aigle&lt;/a&gt; (comme avec &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Forme-Bestiale-I.html&quot; title=&quot;Forme bestiale I&quot;&gt;forme bestiale I&lt;/a&gt;&lt;/i&gt; mais avec la vitesse de vol de 24 m) pendant 10 minutes maximum, et conf&#232;re un bonus de comp&#233;tence de +5 aux tests de &lt;a class=&quot;pagelink&quot; href=&quot;Perception.html&quot; title=&quot;Perception&quot;&gt;Perception&lt;/a&gt;.&lt;/td&gt;&lt;td&gt;7 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Cape-De-La-Raie-Manta.html&quot; title=&quot;Cape de la raie manta&quot;&gt;Cape de la raie manta&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MJ, A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Tant que le porteur est dans l’eau sal&#233;e, le transforme en &lt;a class=&quot;pagelink&quot; href=&quot;Raie-Manta.html&quot; title=&quot;Raie, Raie manta&quot;&gt;raie manta&lt;/a&gt; (comme avec &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Forme-Bestiale-Ii.html&quot; title=&quot;Forme bestiale II&quot;&gt;forme bestiale II&lt;/a&gt;&lt;/i&gt; mais avec un bonus d’armure naturelle de +3 et la capacit&#233; de respirer sous l’eau) et lui conf&#232;re une attaque de queue infligeant 1d6 points de d&#233;g&#226;ts.&lt;/td&gt;&lt;td&gt;7 200 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Cape-Du-Chasseur.html&quot; title=&quot;Cape du chasseur&quot;&gt;Cape du chasseur&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Jusqu’&#224; 10 minutes par jour, permet &#224; un porteur poss&#233;dant la capacit&#233; &lt;a class=&quot;pagelink&quot; href=&quot;R&#244;deur.html#ENVIRONNEMENTDEPREDILECTION&quot; title=&quot;Le r&#244;deur&quot;&gt;environnement de pr&#233;dilection&lt;/a&gt; de se transformer en un animal natif de cet environnement (comme avec &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Forme-Bestiale-I.html&quot; title=&quot;Forme bestiale I&quot;&gt;forme bestiale I&lt;/a&gt;&lt;/i&gt;) tant qu’il s’y trouve.&lt;/td&gt;&lt;td&gt;7 500 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Cape-Des-Exploits-Audacieux.html&quot; title=&quot;Cape des exploits audacieux&quot;&gt;Cape des exploits audacieux&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MCA&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;re un bonus de r&#233;sistance de +2 aux &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;JDS&quot;&gt;jets de sauvegarde&lt;/a&gt; (ce bonus passe &#224; +4 pendant 1 &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Round.html&quot; title=&quot;round&quot;&gt;round&lt;/a&gt; quand le porteur utilise la capacit&#233; &lt;a class=&quot;pagelink&quot; href=&quot;Bretteur.html#CHARMANTEVIE&quot; title=&quot;Le bretteur&quot;&gt;charmante vie&lt;/a&gt;). Quand le porteur accomplit l’exploit &lt;a class=&quot;pagelink&quot; href=&quot;Exploits-(Bretteur).html#BRAVOURE&quot; title=&quot;Les exploits du bretteur&quot;&gt;bravoure&lt;/a&gt;, il ajoute un d&#233; sur un 5 ou un 6 (plut&#244;t que sur un 6 uniquement).&lt;/td&gt;&lt;td&gt;9 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Cape-Du-Roi-Troll.html&quot; title=&quot;Cape du roi troll&quot;&gt;Cape du roi troll&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;CM&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;re un bonus de comp&#233;tence de +5  aux tests d&#39;&lt;a class=&quot;pagelink&quot; href=&quot;Intimidation.html&quot; title=&quot;Intimidation&quot;&gt;Intimidation&lt;/a&gt;. Trois fois par jour, permet de lancer &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Mains-Br&#251;lantes.html&quot; title=&quot;Mains br&#251;lantes&quot;&gt;mains br&#251;lantes&lt;/a&gt;&lt;/i&gt;.&lt;/td&gt;&lt;td&gt;9 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Cape-Du-Po&#232;te.html&quot; title=&quot;Cape du po&#232;te&quot;&gt;Cape du po&#232;te&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MCA&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Permet a un porteur qui poss&#232;de la capacit&#233; &lt;a class=&quot;pagelink&quot; href=&quot;Barde#Representationbardique.html&quot; title=&quot;repr&#233;sentation bardique&quot;&gt;repr&#233;sentation bardique&lt;/a&gt; d’utiliser des &lt;a class=&quot;pagelink&quot; href=&quot;Scalde-.html#CHANTDERAGE&quot; title=&quot;Le scalde&quot;&gt;chant de rage&lt;/a&gt; comme un &lt;a class=&quot;pagelink&quot; href=&quot;Scalde.html&quot; title=&quot;Le scalde&quot;&gt;scalde&lt;/a&gt; de niveau 4 en en d&#233;pensant des rounds. Permet &#224; un porteur qui poss&#232;de la capacit&#233; &lt;a class=&quot;pagelink&quot; href=&quot;Scalde-.html#CHANTDERAGE&quot; title=&quot;Le scalde&quot;&gt;chant de rage&lt;/a&gt; d’utiliser l’&lt;a class=&quot;pagelink&quot; href=&quot;Repr&#233;sentations.html#INSPIRATIONVAILLANTE&quot; title=&quot;Les repr&#233;sentations bardiques du barde&quot;&gt;inspiration vaillante&lt;/a&gt; et l’&lt;a class=&quot;pagelink&quot; href=&quot;Repr&#233;sentations.html#INSPIRATIONTALENTUEUSE&quot; title=&quot;Les repr&#233;sentations bardiques du barde&quot;&gt;inspiration talentueuse&lt;/a&gt; comme un &lt;a class=&quot;pagelink&quot; href=&quot;Barde.html&quot; title=&quot;Le barde&quot;&gt;barde&lt;/a&gt; de niveau 4 en en d&#233;pensant des rounds. Peut accorder un &lt;a class=&quot;pagelink&quot; href=&quot;Scalde.html#POUVOIRDERAGE&quot; title=&quot;Le scalde&quot;&gt; pouvoir de rage&lt;/a&gt; choisi &#224; la fabrication aux cr&#233;atures affect&#233;es par le chant de rage du porteur &#224; la place des siens.&lt;/td&gt;&lt;td&gt;9 750 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Cape-Cocon.html&quot; title=&quot;Cape cocon&quot;&gt;Cape cocon&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Tant que le porteur est endormi (magiquement ou non), conf&#232;re un bonus d’alt&#233;ration de +4 &#224; l’armure naturelle et le prot&#232;ge contre les coups critiques et les attaques sournoises (comme avec une armure de &lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Propri&#233;t&#233;s-Sp&#233;ciales-Des-Armures-Et-Des-Boucliers#D&#233;fense-(L&#233;g&#232;re).html&quot; title=&quot;d&#233;fense l&#233;g&#232;re (propri&#233;t&#233;)&quot;&gt;d&#233;fense l&#233;g&#232;re&lt;/a&gt;).&lt;/td&gt;&lt;td&gt;10 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Cape-De-Marcheur-Du-Cr&#233;puscule.html&quot; title=&quot;Cape de marcheur du cr&#233;puscule&quot;&gt;Cape de marcheur du cr&#233;puscule&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;re la &lt;a class=&quot;pagelink&quot; href=&quot;Vision-Nocturne-(Capacit&#233;).html&quot; title=&quot;Vision nocturne (Ext)&quot;&gt;vision nocturne&lt;/a&gt; en permanence. Une fois par jour, peut entourer le porteur de t&#233;n&#232;bres (comme avec &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;T&#233;n&#232;bres.html&quot; title=&quot;T&#233;n&#232;bres&quot;&gt;t&#233;n&#232;bres&lt;/a&gt;&lt;/i&gt;), lui conf&#233;rant la &lt;a class=&quot;pagelink&quot; href=&quot;Capacit&#233;s-Sp&#233;ciales.html#VISIONDANSLENOIR&quot; title=&quot;Les capacit&#233;s sp&#233;ciales&quot;&gt;vision dans le noir&lt;/a&gt; (18m).&lt;/td&gt;&lt;td&gt;10 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Cape-De-Pierre.html&quot; title=&quot;Cape de pierre&quot;&gt;Cape de pierre&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Peut conf&#233;rer une &lt;a class=&quot;pagelink&quot; href=&quot;R&#233;duction-De-D&#233;g&#226;ts-(Capacit&#233;).html&quot; title=&quot;RD&quot;&gt;RD&lt;/a&gt; 5/adamantium et un bonus de circonstance de +5 aux tests de &lt;a class=&quot;pagelink&quot; href=&quot;Discr&#233;tion.html&quot; title=&quot;Discr&#233;tion&quot;&gt;Discr&#233;tion&lt;/a&gt; &#224; volont&#233;. Tant que ce pouvoir est actif, le porteur perd son bonus de &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Dexterite.html&quot; title=&quot;La Dext&#233;rit&#233;&quot;&gt;Dext&#233;rit&#233;&lt;/a&gt; &#224; la &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Ca.html&quot; title=&quot;CA&quot;&gt;CA&lt;/a&gt;.&lt;/td&gt;&lt;td&gt;10 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&amp;emsp; &lt;a class=&quot;pagelink&quot; href=&quot;Cape-De-Pierre.html&quot; title=&quot;Cape de pierre&quot;&gt;Cape de pierre sup&#233;rieure&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Fonctionne comme la &lt;i&gt;Cape de Pierre&lt;/i&gt;, mais la &lt;a class=&quot;pagelink&quot; href=&quot;R&#233;duction-De-D&#233;g&#226;ts-(Capacit&#233;).html&quot; title=&quot;RD&quot;&gt;RD&lt;/a&gt; s’&#233;l&#232;ve &#224; 10/adamantium.&lt;/td&gt;&lt;td&gt;| 20 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Spalli&#232;res-Du-Taureau.html&quot; title=&quot;Spalli&#232;res du taureau&quot;&gt;Spalli&#232;res du taureau&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;re un bonus de +2 au &lt;a class=&quot;pagelink&quot; href=&quot;Manœuvres-Offensives#Dmd.html&quot; title=&quot;DMD&quot;&gt;DMD&lt;/a&gt; contre les manœuvres de &lt;a class=&quot;pagelink&quot; href=&quot;Manœuvres-Offensives.html#BOUSCULADE&quot; title=&quot;Les manœuvres offensives&quot;&gt;bousculade&lt;/a&gt;. Lorsque le porteur effectue une telle manœuvre, il peut lancer 2 jets et conserver le meilleur r&#233;sultat.&lt;/td&gt;&lt;td&gt;10 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Cape-De-Prestidigitateur.html&quot; title=&quot;Cape de prestidigitateur&quot;&gt;Cape de prestidigitateur&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MJ, A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Une fois par jour, permet de lancer &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Porte-Dimensionnelle.html&quot; title=&quot;Porte dimensionnelle&quot;&gt;porte dimensionnelle&lt;/a&gt;&lt;/i&gt; (porteur uniquement).&lt;/td&gt;&lt;td&gt;10 800 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Spalli&#232;res-Du-Lion-Vigilant.html&quot; title=&quot;Spalli&#232;res du lion vigilant&quot;&gt;Spalli&#232;res du lion vigilant&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Deux fois par jour, lorsque le porteur r&#233;ussit un test d’&lt;a class=&quot;pagelink&quot; href=&quot;Acrobaties.html&quot; title=&quot;Acrobaties&quot;&gt;Acrobaties&lt;/a&gt; pour traverser l’espace contr&#244;l&#233; par une cr&#233;ature, attaque cette derni&#232;re.&lt;/td&gt;&lt;td&gt;10 800 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Cape-Dombre-Et-D&#233;clat.html&quot; title=&quot;Cape d&amp;#39;ombre et d&amp;#39;&#233;clat&quot;&gt;Cape d&#39;ombre et d&#39;&#233;clat&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;RSE&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Cette cape a deux fonctions, soit elle conf&#232;re un bonus d&#39;alt&#233;ration de +2 au &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Charisme.html&quot; title=&quot;Le Charisme&quot;&gt;Charisme&lt;/a&gt;, soit elle conf&#232;re un bonus de comp&#233;tence de +2 aux tests de &lt;a class=&quot;pagelink&quot; href=&quot;Discr&#233;tion.html&quot; title=&quot;Discr&#233;tion&quot;&gt;Discr&#233;tion&lt;/a&gt; et permet de lancer &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Flou.html&quot; title=&quot;Flou&quot;&gt;flou&lt;/a&gt;&lt;/i&gt; trois fois par jour.&lt;/td&gt;&lt;td&gt;11 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Cape-Du-Lion.html&quot; title=&quot;Cape du lion&quot;&gt;Cape du lion&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;re un bonus de r&#233;sistance de +2 aux &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat.html#JETDESAUVEGARDE&quot; title=&quot;Valeurs de combat&quot;&gt;jets de sauvegarde&lt;/a&gt; contre les effets mentaux et la terreur, et un bonus de circonstance de +2 aux tests d’&lt;a class=&quot;pagelink&quot; href=&quot;Intimidation.html&quot; title=&quot;Intimidation&quot;&gt;Intimidation&lt;/a&gt;. Une fois par jour, permet de se transformer en &lt;a class=&quot;pagelink&quot; href=&quot;Lion.html&quot; title=&quot;Lion&quot;&gt;lion&lt;/a&gt; (comme avec &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Forme-Bestiale-Ii.html&quot; title=&quot;Forme bestiale II&quot;&gt;forme bestiale II&lt;/a&gt;&lt;/i&gt;) pendant 10 minutes. Un porteur avec la capacit&#233; &lt;a class=&quot;pagelink&quot; href=&quot;Paladin.html#CHATIMENTDUMAL&quot; title=&quot;Le paladin&quot;&gt;ch&#226;timent du mal&lt;/a&gt; ou &lt;a class=&quot;pagelink&quot; href=&quot;Antipaladin.html#CHATIMENTDUBIEN&quot; title=&quot;L&amp;#39;antipaladin&quot;&gt;du bien&lt;/a&gt; peut en d&#233;penser une utilisation pour r&#233;utiliser ce dernier pouvoir.&lt;/td&gt;&lt;td&gt;12 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Cape-Du-Traqueur.html&quot; title=&quot;Cape du traqueur&quot;&gt;Cape du traqueur&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;CMy&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;re un bonus de +5 aux tests de &lt;a class=&quot;pagelink&quot; href=&quot;Discr&#233;tion.html&quot; title=&quot;Discr&#233;tion&quot;&gt;Discr&#233;tion&lt;/a&gt; et de &lt;a class=&quot;pagelink&quot; href=&quot;Survie.html&quot; title=&quot;Survie&quot;&gt;Survie&lt;/a&gt; pour suivre des traces. Immunise le porteur contre la capacit&#233; &lt;a class=&quot;pagelink&quot; href=&quot;Odorat-(Capacit&#233;).html&quot; title=&quot;Odorat (Ext)&quot;&gt;odorat&lt;/a&gt;. Au prix d&#39;une utilisation de &lt;a class=&quot;pagelink&quot; href=&quot;Glossaire-Mythique#Pouvoirmythique.html&quot; title=&quot;pouvoir mythique&quot;&gt;pouvoir mythique&lt;/a&gt;, peut conf&#233;rer les effets d&#39;une &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Invisibilit&#233;-Supr&#234;me.html&quot; title=&quot;Invisibilit&#233; supr&#234;me&quot;&gt;invisibilit&#233; supr&#234;me&lt;/a&gt;&lt;/i&gt; difficilement r&#233;v&#233;lable (qui se termine 1 minute apr&#232;s avoir port&#233; une attaque) pendant 1 heure.&lt;/td&gt;&lt;td&gt;12 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Houppelande-De-Spores.html&quot; title=&quot;Houppelande de spores&quot;&gt;Houppelande de spores&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;re un bonus de r&#233;sistance de +4 aux &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat.html#JETDESAUVEGARDE&quot; title=&quot;Valeurs de combat&quot;&gt;jets de sauvegarde&lt;/a&gt; contre les maladies. Une fois par jour, peut infliger 1d6 puis 1d3 points de d&#233;g&#226;ts pendant 3 &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Round.html&quot; title=&quot;round&quot;&gt;rounds&lt;/a&gt; aux cr&#233;atures adjacentes au porteur.&lt;/td&gt;&lt;td&gt;13 400 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Cape-De-Feinte.html&quot; title=&quot;Cape de feinte&quot;&gt;Cape de feinte&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MCA&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Trois fois par jour, peut faire perdre son bonus de &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Dexterite.html&quot; title=&quot;La Dext&#233;rit&#233;&quot;&gt;Dext&#233;rit&#233;&lt;/a&gt; &#224; la &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Ca.html&quot; title=&quot;CA&quot;&gt;CA&lt;/a&gt; &#224; un cr&#233;ature jusqu’au prochain tout du porteur (peut &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables#H&#233;b&#233;t&#233;.html&quot; title=&quot;H&#233;b&#233;t&#233;&quot;&gt;h&#233;b&#233;ter&lt;/a&gt; la cr&#233;ature pendant la m&#234;me dur&#233;e si un porteur &lt;a class=&quot;pagelink&quot; href=&quot;Bretteur.html&quot; title=&quot;Le bretteur&quot;&gt;bretteur&lt;/a&gt; accomplit l’exploit &lt;a class=&quot;pagelink&quot; href=&quot;Exploits-(Bretteur).html#FEINTEDEQUALITE&quot; title=&quot;Les exploits du bretteur&quot;&gt;feinte de qualit&#233;&lt;/a&gt; ou utilise ce pouvoir).&lt;/td&gt;&lt;td&gt;14 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Cape-D&#233;vasion-Radieuse.html&quot; title=&quot;Cape d’&#233;vasion radieuse&quot;&gt;Cape d’&#233;vasion radieuse&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Manifeste les effets du sort &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Lumi&#232;re.html&quot; title=&quot;Lumi&#232;re&quot;&gt;lumi&#232;re&lt;/a&gt;&lt;/i&gt; (&#224; 3m) en permanence. Deux fois par jour, peut &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables.html#Aveugl&#233;&quot; title=&quot;Les &#233;tats pr&#233;judiciables&quot;&gt;aveugler&lt;/a&gt; toutes les cr&#233;atures &#224; 6 m ou moins du porteur pendant 1d4 &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Round.html&quot; title=&quot;round&quot;&gt;rounds&lt;/a&gt; puis conf&#233;rer les effets du sort &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Invisibilit&#233;.html&quot; title=&quot;Invisibilit&#233;&quot;&gt;invisibilit&#233;&lt;/a&gt;&lt;/i&gt; &#224; ce dernier pendant 1 minute maximum.&lt;/td&gt;&lt;td&gt;14 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Cape-De-Laraign&#233;e.html&quot; title=&quot;Cape de l&amp;#39;araign&#233;e&quot;&gt;Cape de l’araign&#233;e&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MJ, A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;re un bonus de chance de +2 aux jets de &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;Vigueur&quot;&gt;Vigueur&lt;/a&gt; contre le venin des araign&#233;es ainsi que les effets du sort &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Pattes-Daraign&#233;e.html&quot; title=&quot;Pattes d&amp;#39;araign&#233;e&quot;&gt;pattes d’araign&#233;e&lt;/a&gt;&lt;/i&gt; en permanence. Le porteur se d&#233;place normalement et sans risque dans les toiles (magiques ou naturelles). Une fois par jour, permet de lancer &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Toile-Daraign&#233;e.html&quot; title=&quot;Toile d&amp;#39;araign&#233;e&quot;&gt;toile d’araign&#233;e&lt;/a&gt;&lt;/i&gt;.&lt;/td&gt;&lt;td&gt;14 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Cape-Tentaculaire.html&quot; title=&quot;Cape tentaculaire&quot;&gt;Cape tentaculaire&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Deux fois par jour, peut conf&#233;rer deux attaques de tentacule infligeant des d&#233;g&#226;ts contondants selon sa taille avec une allonge de 3m et la capacit&#233; &lt;a class=&quot;pagelink&quot; href=&quot;&#201;treinte-(Capacit&#233;).html&quot; title=&quot;&#201;treinte (Ext)&quot;&gt;&#233;treinte&lt;/a&gt; avec un bonus de +4 aux tests de &lt;a class=&quot;pagelink&quot; href=&quot;Manœuvres-Offensives.html#LUTTE&quot; title=&quot;Les manœuvres offensives&quot;&gt;lutte&lt;/a&gt;, pendant 1 minute.&lt;/td&gt;&lt;td&gt;14 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Poncho-De-Franc-Tireur.html&quot; title=&quot;Poncho de franc-tireur&quot;&gt;Poncho de franc-tireur&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;re un bonus de chance de +2 &#224; la &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Ca.html&quot; title=&quot;CA&quot;&gt;CA&lt;/a&gt; au contact. Une fois par jour, permet de se jeter &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables.html#ATERRE&quot; title=&quot;Les &#233;tats pr&#233;judiciables&quot;&gt;&#224; terre&lt;/a&gt; pour annuler une attaque de contact &#224; distance. Ces pouvoirs ne fonctionnent que contre les attaques d’armes &#224; feu et la magie hostile.&lt;/td&gt;&lt;td&gt;14 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Spalli&#232;res-&#192;-Pointes-D&#233;moniaques.html&quot; title=&quot;Spalli&#232;res &#224; pointes d&#233;moniaques&quot;&gt;Spalli&#232;res &#224; pointes d&#233;moniaques&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Similaires &#224; des pointes pour armure +2 qui infligent 1d2 points de d&#233;g&#226;ts de saignement suppl&#233;mentaires. Elles augmentent les d&#233;g&#226;ts des pointes pour armure d&#233;j&#224; port&#233;es d’une cat&#233;gorie.&lt;/td&gt;&lt;td&gt;14 350 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Cape-Confortable.html&quot; title=&quot;Cape confortable&quot;&gt;Cape confortable&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;re un bonus de comp&#233;tence de +4 aux jets de sauvegarde contre les maladies, l’&lt;a class=&quot;pagelink&quot; href=&quot;Absorption-D&#233;nergie-(Capacit&#233;).html&quot; title=&quot;Absorption d’&#233;nergie (Sur)&quot;&gt;absorption d’&#233;nergie&lt;/a&gt;, les poisons, et les effets de &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables.html#Fatigu&#233;&quot; title=&quot;Les &#233;tats pr&#233;judiciables&quot;&gt;fatigue&lt;/a&gt; et d’&lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables.html#&#233;puis&#233;&quot; title=&quot;Les &#233;tats pr&#233;judiciables&quot;&gt;&#233;puisement&lt;/a&gt; ainsi que les effets du sort &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Endurance-Aux-&#201;nergies-Destructives.html&quot; title=&quot;Endurance aux &#233;nergies destructives&quot;&gt;endurance aux &#233;nergies destructives&lt;/a&gt;&lt;/i&gt; en permanence. Les repos de 8 heures rendent 2 points de vie par &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Desdevie.html&quot; title=&quot;DV&quot;&gt;DV&lt;/a&gt; et ceux de 24 heures 5 points de vie par &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Desdevie.html&quot; title=&quot;DV&quot;&gt;DV&lt;/a&gt;.&lt;/td&gt;&lt;td&gt;15 600 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Ch&#226;le-De-M&#233;g&#232;re.html&quot; title=&quot;Ch&#226;le de m&#233;g&#232;re&quot;&gt;Ch&#226;le de m&#233;g&#232;re&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Donne l’apparence d’une v&#233;n&#233;rable femme de sa race au porteur (sans bonus ni malus li&#233;s &#224; l’&#226;ge) tant qu’il le porte. Conf&#232;re un bonus de circonstance de +4 aux tests de comp&#233;tence bas&#233;s sur le &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Charisme.html&quot; title=&quot;Le Charisme&quot;&gt;Charisme&lt;/a&gt; pour para&#238;tre amical, inoffensif, sans d&#233;fense ou respectable (+8 avec les enfants). Permet de rejoindre un cercle de geunaude.&lt;/td&gt;&lt;td&gt;16 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;P&#232;lerine-De-Bateleur.html&quot; title=&quot;P&#232;lerine de bateleur&quot;&gt;P&#232;lerine de bateleur&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;re un bonus de +8 aux tests d’&lt;a class=&quot;pagelink&quot; href=&quot;Escamotage.html&quot; title=&quot;Escamotage&quot;&gt;Escamotage&lt;/a&gt;. Peut stocker un un objet de 1,50m de c&#244;t&#233; ou moins pesant jusqu’&#224; 50kg ou moins dans un espace extra-dimensionnel pendant 1 heure maximum.&lt;/td&gt;&lt;td&gt;17 200 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Cape-De-R&#234;ves-Ail&#233;s.html&quot; title=&quot;Cape de r&#234;ves ail&#233;s&quot;&gt;Cape de r&#234;ves ail&#233;s&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;&lt;i&gt;ISG&lt;/i&gt;&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Une fois par jour, permet de lancer &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Manteau-De-Gu&#234;pes.html&quot; title=&quot;Manteau de gu&#234;pes&quot;&gt;manteau de gu&#234;pes&lt;/a&gt;&lt;/i&gt; (sans poison, d&#233;g&#226;ts complets aux cr&#233;atures intangibles) et &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Poussi&#232;re-Scintillante.html&quot; title=&quot;Poussi&#232;re scintillante&quot;&gt;poussi&#232;re scintillante&lt;/a&gt;&lt;/i&gt;.&lt;/td&gt;&lt;td&gt;17 500 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;&#201;tole-De-Justice.html&quot; title=&quot;&#201;tole de justice&quot;&gt;&#233;tole de justice&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;re un bonus de +5 aux tests de &lt;a class=&quot;pagelink&quot; href=&quot;Psychologie.html&quot; title=&quot;Psychologie&quot;&gt;Psychologie&lt;/a&gt;. Jusqu’&#224; 5 minutes par jour, peut manifester les effets du sort &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Zone-De-V&#233;rit&#233;.html&quot; title=&quot;Zone de v&#233;rit&#233;&quot;&gt;zone de v&#233;rit&#233;&lt;/a&gt;&lt;/i&gt;. Lorsqu’il lance &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;D&#233;tection-Du-Chaos.html&quot; title=&quot;D&#233;tection du Chaos&quot;&gt;d&#233;tection du Chaos&lt;/a&gt;&lt;/i&gt;, &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;D&#233;tection-Du-Mal.html&quot; title=&quot;D&#233;tection du Mal&quot;&gt;du Mal&lt;/a&gt;&lt;/i&gt;, &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;D&#233;tection-De-La-Loi.html&quot; title=&quot;D&#233;tection de la Loi&quot;&gt;de la Loi&lt;/a&gt;&lt;/i&gt; ou &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;D&#233;tection-Du-Bien.html&quot; title=&quot;D&#233;tection du Bien&quot;&gt;du Bien&lt;/a&gt;&lt;/i&gt;, le porteur obtient les informations du troisi&#232;me &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Round.html&quot; title=&quot;round&quot;&gt;round&lt;/a&gt; au d&#233;but du tour suivant l’incantation. Conf&#232;re &#224; un &lt;a class=&quot;pagelink&quot; href=&quot;Inquisiteur.html&quot; title=&quot;L&amp;#39;inquisiteur&quot;&gt;inquisiteur&lt;/a&gt; un bonus aux tests de &lt;a class=&quot;pagelink&quot; href=&quot;Perception.html&quot; title=&quot;Perception&quot;&gt;Perception&lt;/a&gt; et au &lt;a class=&quot;pagelink&quot; href=&quot;Manœuvres-Offensives#Dmd.html&quot; title=&quot;DMD&quot;&gt;DMD&lt;/a&gt; (comme avec une arme &lt;a class=&quot;pagelink&quot; href=&quot;Descriptions-Individuelles-Des-Propri&#233;t&#233;s-Sp&#233;ciales-Des-Armes#Juge.html&quot; title=&quot;juge (propri&#233;t&#233;)&quot;&gt;de juge&lt;/a&gt;) lorsqu’il utilise sa capacit&#233; &lt;a class=&quot;pagelink&quot; href=&quot;Inquisiteur.html#JUGEMENT&quot; title=&quot;L&amp;#39;inquisiteur&quot;&gt;jugement&lt;/a&gt;.&lt;/td&gt;&lt;td&gt;18 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Cape-De-La-M&#233;duse.html&quot; title=&quot;Cape de la m&#233;duse&quot;&gt;Cape de la m&#233;duse&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Tant que le porteur est dans l’eau sal&#233;e, conf&#232;re un &lt;a class=&quot;pagelink&quot; href=&quot;Modificateurs-De-Combat.html#CAMOUGLAGE&quot; title=&quot;Modificateurs de combat&quot;&gt;camouflage&lt;/a&gt; de 20%, la capacit&#233; &#224; respirer sous l’eau et une vitesse de nage de 6m. Dans cette situation, inflige 1 point de d&#233;g&#226;ts aux cr&#233;atures qui terminent leur tour sur une case adjacente au porteur et peut les rendre &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables.html#Fi&#233;vreux&quot; title=&quot;Les &#233;tats pr&#233;judiciables&quot;&gt;fi&#233;vreuses&lt;/a&gt;.&lt;/td&gt;&lt;td&gt;19 200 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Cape-De-Diplomate.html&quot; title=&quot;Cape de diplomate&quot;&gt;Cape de diplomate&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E, MR&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;re un bonus de comp&#233;tence de +5 aux tests de &lt;a class=&quot;pagelink&quot; href=&quot;Diplomatie.html&quot; title=&quot;Diplomatie&quot;&gt;Diplomatie&lt;/a&gt; et de &lt;a class=&quot;pagelink&quot; href=&quot;Psychologie.html&quot; title=&quot;Psychologie&quot;&gt;Psychologie&lt;/a&gt;. Une fois par jour, lorsque le porteur effectue un tel test, il peut lancer 2 jets et conserver le meilleur r&#233;sultat. Augmente l’impact des tests de &lt;a class=&quot;pagelink&quot; href=&quot;Diplomatie.html&quot; title=&quot;Diplomatie&quot;&gt;Diplomatie&lt;/a&gt; visant &#224; modifier l’attitude d’une cr&#233;ature.&lt;/td&gt;&lt;td&gt;20 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Cape-Tranchante.html&quot; title=&quot;Cape tranchante&quot;&gt;Cape tranchante&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Permet d’effectuer une attaque infligeant 2d6 points de d&#233;g&#226;ts &#224; toutes les cr&#233;atures adjacentes par une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Complexe.html&quot; title=&quot;Action complexe&quot;&gt;action complexe&lt;/a&gt;, elle peut &#234;tre enchant&#233;e.&lt;/td&gt;&lt;td&gt;20 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Cape-De-D&#233;placement.html&quot; title=&quot;Cape de d&#233;placement&quot;&gt;Cape de d&#233;placement&lt;/a&gt; mineure&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MJ, A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;re les effets du sort &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Flou.html&quot; title=&quot;Flou&quot;&gt;flou&lt;/a&gt;&lt;/i&gt; en permanence.&lt;/td&gt;&lt;td&gt;24 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&amp;emsp; &lt;a class=&quot;pagelink&quot; href=&quot;Cape-De-D&#233;placement.html&quot; title=&quot;Cape de d&#233;placement&quot;&gt;Cape de d&#233;placement&lt;/a&gt; majeure&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MJ, A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Jusqu’&#224; 15 &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Round.html&quot; title=&quot;round&quot;&gt;rounds&lt;/a&gt; par jour, peut conf&#233;rer les effets du sort &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;D&#233;placement.html&quot; title=&quot;D&#233;placement&quot;&gt;d&#233;placement&lt;/a&gt;&lt;/i&gt;.&lt;/td&gt;&lt;td&gt;| 50 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Peau-De-Lycanthrope.html&quot; title=&quot;Peau de lycanthrope&quot;&gt;Peau de lycanthrope (loup, rat, sanglier)&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;&lt;i&gt;ISR&lt;/i&gt;&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Permet de parler aux animaux proches des loups, rats et sangliers (comme avec &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Communication-Avec-Les-Animaux.html&quot; title=&quot;Communication avec les animaux&quot;&gt;communication avec les animaux&lt;/a&gt;&lt;/i&gt;). Un porteur &lt;a class=&quot;pagelink&quot; href=&quot;Changepeau-(Race).html&quot; title=&quot;Les changepeaux&quot;&gt;changepeau&lt;/a&gt; dont l&#39;h&#233;ritage correspond &#224; l&#39;un des animaux associ&#233;s peut prendre sa forme comme avec &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Forme-Bestiale-I.html&quot; title=&quot;Forme bestiale I&quot;&gt;forme bestiale I&lt;/a&gt;&lt;/i&gt; (ainsi que la taille et l&#39;apparence) aussi longtemps qu&#39;il le souhaite.&lt;/td&gt;&lt;td&gt;24 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Peau-De-Lycanthrope.html&quot; title=&quot;Peau de lycanthrope&quot;&gt;Peau de lycanthrope (chauve-sourris, crocodile, grizzly, tigre)&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;&lt;i&gt;ISR&lt;/i&gt;&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;M&#234;mes effets, mais avec les animaux proches des chauves-sourris, crocodiles, grizzly et tigres &#224; la place.&lt;/td&gt;&lt;td&gt;| 40 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Cape-De-La-Chauve-Souris.html&quot; title=&quot;Cape de la chauve-souris&quot;&gt;Cape de la chauve-souris&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MJ, A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;re un bonus de comp&#233;tence de +5 aux tests de &lt;a class=&quot;pagelink&quot; href=&quot;Discr&#233;tion.html&quot; title=&quot;Discr&#233;tion&quot;&gt;Discr&#233;tion&lt;/a&gt;. Permet de se pendre la t&#234;te en bas aux plafonds. Permet de lancer &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Sort-Vol.html&quot; title=&quot;Vol&quot;&gt;vol&lt;/a&gt;&lt;/i&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Vol.html&quot; title=&quot;Vol&quot;&gt;Vol&lt;/a&gt; +7) ou de se transformer en &lt;a class=&quot;pagelink&quot; href=&quot;Chauve-Souris.html&quot; title=&quot;Chauve-souris&quot;&gt;chauve-souris&lt;/a&gt; (comme avec &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Forme-Bestiale-Iii.html&quot; title=&quot;Forme bestiale III&quot;&gt;forme bestiale III&lt;/a&gt;&lt;/i&gt; mais avec la vitesse de vol de 12m), jusqu’&#224; 7 minutes par jour chacun (rendant la cape inutile pendant la m&#234;me dur&#233;e ensuite).&lt;/td&gt;&lt;td&gt;26 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Cape-D&#233;t&#233;-Et-Dhiver.html&quot; title=&quot;Cape d&amp;#39;&#233;t&#233; et d&amp;#39;hiver&quot;&gt;Cape d&#39;&#233;t&#233; et d&#39;hiver&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;&lt;i&gt;ISR&lt;/i&gt;&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Une fois par jour, permet d&#39;utiliser &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Bouclier-De-Feu.html&quot; title=&quot;Bouclier de feu&quot;&gt;bouclier de feu&lt;/a&gt;&lt;/i&gt; adapt&#233; &#224; la temp&#233;rature environnante. Un porteur triaxien obtient une &lt;a class=&quot;pagelink&quot; href=&quot;R&#233;sistance-(Capacit&#233;).html&quot; title=&quot;R&#233;sistance (aux &#233;nergies destructrices) (Ext)&quot;&gt;r&#233;sistance aux &#233;nergies destructives&lt;/a&gt; de 10 au feu (s&#39;il est n&#233; de l&#39;&#233;t&#233;) ou au froid (s&#39;il est n&#233; de l&#39;hiver), ou une r&#233;sistance de 5 au feu et au froid (s&#39;il est transitionnel).&lt;/td&gt;&lt;td&gt;30 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Cape-De-Bandit-De-Grand-Chemin.html&quot; title=&quot;Cape de bandit de grand chemin&quot;&gt;Cape de bandit de grand chemin&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;re un bonus de comp&#233;tence de +5 aux tests de &lt;a class=&quot;pagelink&quot; href=&quot;Bluff.html&quot; title=&quot;Bluff&quot;&gt;Bluff&lt;/a&gt; ou de &lt;a class=&quot;pagelink&quot; href=&quot;Discr&#233;tion.html&quot; title=&quot;Discr&#233;tion&quot;&gt;Discr&#233;tion&lt;/a&gt; (pas les deux en m&#234;me temps). Permet d&#39;effectuer un test d&#39;&lt;a class=&quot;pagelink&quot; href=&quot;&#201;vasion.html&quot; title=&quot;&#201;vasion&quot;&gt;&#233;vasion&lt;/a&gt; imm&#233;diatement pour &#233;viter d&#39;&#234;tre &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables#Agripp&#233;.html&quot; title=&quot;Agripp&#233;&quot;&gt;agripp&#233;&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables#Immobilis&#233;.html&quot; title=&quot;Immobilis&#233;&quot;&gt;immobilis&#233;&lt;/a&gt; ou restreint (comme avec &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Ordre-Lib&#233;rateur.html&quot; title=&quot;Ordre lib&#233;rateur&quot;&gt;ordre lib&#233;rateur&lt;/a&gt;&lt;/i&gt;).&lt;/td&gt;&lt;td&gt;32 500 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Cape-De-D&#233;sarmement.html&quot; title=&quot;Cape de d&#233;sarmement&quot;&gt;Cape de d&#233;sarmement&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MCA&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Permet d’effectuer une manœuvre de &lt;a class=&quot;pagelink&quot; href=&quot;Manœuvres-Offensives#Desarmement.html&quot; title=&quot;d&#233;sarmement&quot;&gt;d&#233;sarmement&lt;/a&gt; sans provoquer d’&lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Attaquedopportunite.html&quot; title=&quot;attaque d&amp;#39;opportunit&#233;&quot;&gt;attaque d&#39;opportunit&#233;&lt;/a&gt; par une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Rapide.html&quot; title=&quot;Action rapide&quot;&gt;action rapide&lt;/a&gt; (Un personnage qui poss&#232;de la capacit&#233; &lt;a class=&quot;pagelink&quot; href=&quot;Bretteur#Panache.html&quot; title=&quot;panache&quot;&gt;panache&lt;/a&gt; peut en d&#233;penser 1 point pour b&#233;n&#233;ficier d’un bonus de comp&#233;tence de +5 &#224; son test).&lt;/td&gt;&lt;td&gt;35 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Spalli&#232;res-De-Juggernaut.html&quot; title=&quot;Spalli&#232;res de juggernaut&quot;&gt;Spalli&#232;res de juggernaut&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;re un bonus de +4 au &lt;a class=&quot;pagelink&quot; href=&quot;Manœuvres-Offensives#Dmd.html&quot; title=&quot;DMD&quot;&gt;DMD&lt;/a&gt; et la capacit&#233; &lt;a class=&quot;pagelink&quot; href=&quot;F&#233;rocit&#233;-(Capacit&#233;).html&quot; title=&quot;F&#233;rocit&#233; (Ext)&quot;&gt;f&#233;rocit&#233;&lt;/a&gt;. Peut conf&#233;rer les effets du sort &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Agrandissement.html&quot; title=&quot;Agrandissement&quot;&gt;agrandissement&lt;/a&gt;&lt;/i&gt; &#224; volont&#233;. Trois fois par jour apr&#232;s que le porteur ait tu&#233; un adversaire, conf&#232;re les effets du sort &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Juggernaut-Mortel.html&quot; title=&quot;Juggernaut mortel&quot;&gt;juggernaut mortel&lt;/a&gt;&lt;/i&gt; pendant 1 minute.&lt;/td&gt;&lt;td&gt;40 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Cape-De-Charlatan.html&quot; title=&quot;Cape de charlatan&quot;&gt;Cape de charlatan&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Trois fois par jour, permet de lancer &lt;a class=&quot;pagelink&quot; href=&quot;Porte-Dimensionnelle.html&quot; title=&quot;Porte dimensionnelle&quot;&gt;porte dimensionnelle&lt;/a&gt; (porteur uniquement). Une fois par jour, permet de lancer &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Forme-&#201;th&#233;r&#233;e.html&quot; title=&quot;Forme &#233;th&#233;r&#233;e&quot;&gt;forme &#233;th&#233;r&#233;e&lt;/a&gt;&lt;/i&gt;.&lt;/td&gt;&lt;td&gt;45 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Ailes-De-Vol.html&quot; title=&quot;Ailes de vol&quot;&gt;Ailes de vol&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MJ, A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Peut conf&#233;rer un bonus de comp&#233;tence de +5 aux tests de &lt;a class=&quot;pagelink&quot; href=&quot;Vol.html&quot; title=&quot;Vol&quot;&gt;Vol&lt;/a&gt; et une vitesse de vol de 18m (manœuvrabilit&#233; moyenne), &#224; volont&#233;.&lt;/td&gt;&lt;td&gt;54 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Cape-Du-Ph&#233;nix.html&quot; title=&quot;Cape du ph&#233;nix&quot;&gt;Cape du ph&#233;nix&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;CMy&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Jusqu&#39;&#224; 10 &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Round.html&quot; title=&quot;round&quot;&gt;rounds&lt;/a&gt; par jour, peut conf&#233;rer la capacit&#233; &lt;a class=&quot;pagelink&quot; href=&quot;Combustion-(Capacit&#233;).html&quot; title=&quot;Combustion (Ext)&quot;&gt;combustion&lt;/a&gt; aux attaques &#224; mains nues et naturelles du porteur. Lorsqu&#39;il est r&#233;duit &#224; moins de 0 &lt;a class=&quot;pagelink&quot; href=&quot;Point-De-Vie.html&quot; title=&quot;pv&quot;&gt;pv&lt;/a&gt; et au prix d&#39;une utilisation de &lt;a class=&quot;pagelink&quot; href=&quot;Glossaire-Mythique#Pouvoirmythique.html&quot; title=&quot;pouvoir mythique&quot;&gt;pouvoir mythique&lt;/a&gt;, le porteur peut b&#233;n&#233;ficier des effets d&#39;un &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Souffle-De-Vie.html&quot; title=&quot;Souffle de vie&quot;&gt;souffle de vie&lt;/a&gt;&lt;/i&gt; et d&#39;un &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Corps-&#201;l&#233;mentaire-Ii.html&quot; title=&quot;Corps &#233;l&#233;mentaire II&quot;&gt;corps &#233;l&#233;mentaire II&lt;/a&gt;&lt;/i&gt; (feu uniquement, avec une vitesse de vol de 15m).&lt;/td&gt;&lt;td&gt;55 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Cape-&#201;th&#233;r&#233;e.html&quot; title=&quot;Cape &#233;th&#233;r&#233;e&quot;&gt;Cape &#233;th&#233;r&#233;e&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MJ, A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Jusqu’&#224; 10 minutes par jour, peut conf&#233;rer les effets du sort &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Forme-&#201;th&#233;r&#233;e.html&quot; title=&quot;Forme &#233;th&#233;r&#233;e&quot;&gt;forme &#233;th&#233;r&#233;e&lt;/a&gt;&lt;/i&gt;.&lt;/td&gt;&lt;td&gt;55 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Cape-Des-Ombres-Sourdes.html&quot; title=&quot;Cape des ombres sourdes&quot;&gt;Cape des ombres sourdes&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;&lt;i&gt;UI&lt;/i&gt;&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;&#192; volont&#233;, peut baisser la luminosit&#233; dans un rayon de 9 m d&#39;une cat&#233;gorie et &#233;touffer les sons &#233;mits par le porteur (comme avec &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Manipulation-Des-Sons.html&quot; title=&quot;Manipulation des sons&quot;&gt;manipulation des sons&lt;/a&gt;&lt;/i&gt;) pendant 15 minutes. Une fois par semaine, permet de lancer &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Travers&#233;e-Des-Ombres.html&quot; title=&quot;Travers&#233;e des ombres&quot;&gt;travers&#233;e des ombres&lt;/a&gt;&lt;/i&gt;. Une seule fois, peut conf&#233;rer les effets de &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Corps-Dombre.html&quot; title=&quot;Corps d&amp;#39;ombre&quot;&gt;corps d&#39;ombre&lt;/a&gt;&lt;/i&gt; pendant 15 minutes.&lt;/td&gt;&lt;td&gt;63 250 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Cape-Dimmolation-Cmy.html&quot; title=&quot;Cape d&amp;#39;immolation (CMy)&quot;&gt;Cape d’immolation (CMy)&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;CMy&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;re une &lt;a class=&quot;pagelink&quot; href=&quot;R&#233;sistance-(Capacit&#233;).html&quot; title=&quot;R&#233;sistance (aux &#233;nergies destructrices) (Ext)&quot;&gt;r&#233;sistance&lt;/a&gt; au feu de 20. Jusqu&#39;&#224; 10 &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Round.html&quot; title=&quot;round&quot;&gt;rounds&lt;/a&gt; par jour, peut conf&#233;rer les effets de &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Bouclier-De-Feu.html&quot; title=&quot;Bouclier de feu&quot;&gt;bouclier de feu&lt;/a&gt;&lt;/i&gt;. Au prix d&#39;une utilisation de &lt;a class=&quot;pagelink&quot; href=&quot;Glossaire-Mythique#Pouvoirmythique.html&quot; title=&quot;pouvoir mythique&quot;&gt;pouvoir mythique&lt;/a&gt;, le porteur peut recharger le pouvoir de la cape, ou infliger des d&#233;g&#226;ts de feu aux cr&#233;atures dans un rayon de 9m autour de lui en leur faisant croire qu&#39;il est mort jusqu&#39;&#224; son prochain tour.&lt;/td&gt;&lt;td&gt;65 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Ailes-De-Gargouille.html&quot; title=&quot;Ailes de gargouille&quot;&gt;Ailes de gargouille&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Jusqu’&#224; 5 minutes par jour, peut conf&#233;rer une vitesse de vol de 18m (manœuvrabilit&#233; moyenne) et une &lt;a class=&quot;pagelink&quot; href=&quot;R&#233;duction-De-D&#233;g&#226;ts-(Capacit&#233;).html&quot; title=&quot;RD&quot;&gt;RD&lt;/a&gt; 10/adamantium.&lt;/td&gt;&lt;td&gt;72 000 po&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Cape-De-La-Vouivre.html&quot; title=&quot;Cape de la vouivre&quot;&gt;Cape de la vouivre&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;A&amp;E&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Conf&#232;re un bonus de r&#233;sistance de +4 aux jets de &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;Volont&#233;&quot;&gt;Volont&#233;&lt;/a&gt; ainsi que les effets du sort &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Feuille-Morte.html&quot; title=&quot;Feuille morte&quot;&gt;feuille morte&lt;/a&gt;&lt;/i&gt; en permanence. Une fois par jour, permet de lancer &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Sort-Vol.html&quot; title=&quot;Vol&quot;&gt;vol&lt;/a&gt;&lt;/i&gt;. Peut conf&#233;rer une attaque de dard infligeant 1d6 points de d&#233;g&#226;ts et les effets du sort &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Empoisonnement.html&quot; title=&quot;Empoisonnement&quot;&gt;empoisonnement&lt;/a&gt;&lt;/i&gt;, &#224; volont&#233;.&lt;/td&gt;&lt;td&gt;78 600 po&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;
